const $=s=>document.querySelector(s),status=message=>{$('#status').textContent=message;};
async function api(path,method='GET',body){const response=await fetch('/api/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(15000)});if(!response.headers.get('content-type')?.includes('application/json'))throw Error('سجّل الدخول ثم أعد المحاولة');const result=await response.json();if(!response.ok)throw Error(result.error||'تعذر تنفيذ الطلب');return result;}
const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('setup')){$('#setupCode').value=fragment.get('setup');sessionStorage.setItem('mawazin-setup',fragment.get('setup'));history.replaceState(null,'',location.pathname);}else $('#setupCode').value=sessionStorage.getItem('mawazin-setup')||'';
async function refresh(){const {kitchens}=await api('admin/kitchens');$('#kitchens').replaceChildren();if(!kitchens.length)$('#kitchens').textContent='لا توجد مطابخ بعد. أنشئ المطبخ الأول أعلاه.';for(const kitchen of kitchens){const card=document.createElement('section'),title=document.createElement('h3'),meta=document.createElement('p'),button=document.createElement('button');title.textContent=kitchen.name;meta.textContent=`${kitchen.managers} مدير · ${kitchen.devices} جهاز`;button.textContent='إصدار رابط تفعيل المدير';button.className='button primary';button.onclick=()=>run(button,async()=>{const result=await api('admin/invites','POST',{kitchenId:kitchen.id});$('#inviteUrl').value=result.url;$('#expiry').textContent='ينتهي: '+new Date(result.expiresAt).toLocaleString('ar-DZ');$('#handoff').hidden=false;$('#handoff').scrollIntoView({behavior:'smooth'});status('رابط مدير '+kitchen.name+' جاهز للتسليم.');});card.className='kitchen-card';card.append(title,meta,button);$('#kitchens').append(card);}}
async function run(button,action){button.disabled=true;try{await action();}catch(error){status(error.message);}finally{button.disabled=false;}}
async function start(){try{const session=await api('session');if(session.role!=='admin'){$('#access').hidden=false;status('إدارة المطابخ متاحة للأدمن فقط.');return;}$('#access').hidden=true;$('#management').hidden=false;await refresh();status('جاهز لإدارة المطابخ.');}catch(error){$('#access').hidden=false;status(error.message);}}
$('#setup').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{await api('admin/setup','POST',{code:$('#setupCode').value.trim()});$('#setupCode').value='';sessionStorage.removeItem('mawazin-setup');await start();});};
$('#create').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{const result=await api('admin/kitchens','POST',{name:$('#name').value,importPrevious:$('#importPrevious').checked});e.target.reset();await refresh();status('تم إنشاء '+result.kitchen.name+'. أصدر الآن رابط تفعيل مديره.');});};
$('#refresh').onclick=e=>run(e.currentTarget,refresh);
$('#copy').onclick=e=>run(e.currentTarget,async()=>{await navigator.clipboard.writeText($('#inviteUrl').value);status('تم نسخ رابط التفعيل.');});
void start();
